std::size_t hash1 = ckh->hash1(searchkey);
std::size_t hash2 = ckh->hash2(searchkey);
std::size_t index = hash1 % ckh->size;
std::size_t alt_index = hash2 % ckh->size;

for (std::size_t attempt = 0; attempt < ckh->max_attempts; ++attempt) {
    if (ckh->table[index].key == nullptr) {
        return true; // Not found
    }

    if (ckh->hash1(ckh->table[index].key) == hash1 &&
        std::memcmp(ckh->table[index].key, searchkey, ckh->key_size) == 0) {
        *key = ckh->table[index].key;
        *data = ckh->table[index].data;
        return false; // Found
    }

    index = (index + 1) % ckh->size;
    if (index == alt_index) {
        index = (index + 1) % ckh->size;
    }
}

return true; // Not found after max attempts
// END_CODE

